Part 1 — `swap`, by value and by pointer. Write this program in full:

```c
#include <stdio.h>

void swap_by_value(int a, int b)
{
    int t = a;
    a = b;
    b = t;
    printf("  inside: a = %d, b = %d\n", a, b);   /* swapped copies */
}

void swap_by_pointer(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void)
{
    int x = 1, y = 2;

    printf("by value:   before x = %d, y = %d\n", x, y);
    swap_by_value(x, y);
    printf("by value:   after  x = %d, y = %d\n", x, y);

    printf("by pointer: before x = %d, y = %d\n", x, y);
    swap_by_pointer(&x, &y);
    printf("by pointer: after  x = %d, y = %d\n", x, y);
    return 0;
}
```

Part 2 — walk an array without `[]`. The walk uses only `p + i` and `*`; `&a[i]` appears solely as the oracle you check against. Write this program:

```c
#include <stdio.h>

int main(void)
{
    int a[5] = {10, 20, 30, 40, 50};
    int *p = a;                    /* a decays to &a[0] (full story in I.5) */

    for (int i = 0; i < 5; i++) {
        printf("p + %d = %p   &a[%d] = %p   value = %d\n",
               i, (void *)(p + i), i, (void *)&a[i], *(p + i));
    }
    return 0;
}
```
